package kz.aitu.sdp.assignment6.integration;

import java.util.List;
import java.util.Objects;

/**
 * Immutable maintenance ticket generated by the integration service
 * after running inspection visitors on a flagged grid subtree.
 */
public record MaintenanceTicket(
        String ticketId,
        String targetSubtreeId,
        Severity severity,
        double measuredNetLoadKw,
        List<String> flaggedComponentIds,
        String diagnosis,
        long createdAt
) {
    public enum Severity {
        LOW,
        MEDIUM,
        HIGH,
        CRITICAL
    }

    public MaintenanceTicket {
        Objects.requireNonNull(ticketId, "ticketId cannot be null");
        Objects.requireNonNull(targetSubtreeId, "targetSubtreeId cannot be null");
        Objects.requireNonNull(severity, "severity cannot be null");
        flaggedComponentIds = List.copyOf(flaggedComponentIds);
    }
}
